values
('bmlt-generalpathology1-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Cell injury caused by lack of oxygen is called:","translation":"","options":["Hypoxic injury","Chemical injury","Radiation injury","Immune injury"],"correctIndex":0,"explanation":"Reduced oxygen supply causes hypoxic cell injury.","explanationNe":"अक्सिजनको आपूर्ति कम हुँदा hypoxic cell injury हुन्छ।","topic":"General pathology"}'::jsonb,true),
('bmlt-generalpathology1-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"The most common cause of cellular injury in clinical practice is:","translation":"","options":["Hypoxia","Excess vitamins","High calcium","Dehydration only"],"correctIndex":0,"explanation":"Hypoxia is a major and common mechanism of cell injury.","explanationNe":"Hypoxia कोष क्षतिको प्रमुख र सामान्य कारण हो।","topic":"General pathology"}'::jsonb,true),
('bmlt-generalpathology1-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"The earliest reversible change in many injured cells is:","translation":"","options":["Cell swelling","Nuclear dissolution","Membrane rupture","Calcification"],"correctIndex":0,"explanation":"Failure of ion pumps causes intracellular water accumulation and swelling.","explanationNe":"आयन पम्प बिग्रँदा कोषभित्र पानी जम्मा भई कोष सुन्निन्छ।","topic":"Cell injury"}'::jsonb,true),
('bmlt-generalpathology1-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Programmed cell death is known as:","translation":"","options":["Necrosis","Apoptosis","Gangrene","Autolysis"],"correctIndex":1,"explanation":"Apoptosis is regulated, programmed cell death.","explanationNe":"Apoptosis नियन्त्रित तथा पूर्वनिर्धारित कोष मृत्यु हो।","topic":"Cell injury"}'::jsonb,true),
('bmlt-generalpathology1-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"Uncontrolled cell death with inflammation is generally called:","translation":"","options":["Apoptosis","Necrosis","Mitosis","Metaplasia"],"correctIndex":1,"explanation":"Necrosis commonly involves membrane damage and inflammation.","explanationNe":"Necrosis मा प्रायः कोष झिल्ली बिग्रन्छ र सूजन प्रतिक्रिया हुन्छ।","topic":"Cell injury"}'::jsonb,true),
('bmlt-generalpathology1-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"Replacement of one mature cell type by another mature cell type is:","translation":"","options":["Hyperplasia","Metaplasia","Dysplasia","Anaplasia"],"correctIndex":1,"explanation":"Metaplasia is an adaptive reversible change in which one mature cell type is replaced by another.","explanationNe":"Metaplasia मा एउटा परिपक्व कोष प्रकार अर्को परिपक्व प्रकारले प्रतिस्थापन गर्छ।","topic":"Cell adaptation"}'::jsonb,true),
('bmlt-generalpathology1-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"An increase in the number of cells in a tissue is:","translation":"","options":["Hypertrophy","Hyperplasia","Atrophy","Necrosis"],"correctIndex":1,"explanation":"Hyperplasia means increased cell number.","explanationNe":"Hyperplasia भनेको कोषको संख्या बढ्नु हो।","topic":"Cell adaptation"}'::jsonb,true),
('bmlt-generalpathology1-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"An increase in the size of individual cells is:","translation":"","options":["Hyperplasia","Hypertrophy","Metaplasia","Dysplasia"],"correctIndex":1,"explanation":"Hypertrophy is enlargement of individual cells.","explanationNe":"Hypertrophy मा प्रत्येक कोषको आकार बढ्छ।","topic":"Cell adaptation"}'::jsonb,true),
('bmlt-generalpathology1-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"A localized collection of pus is called:","translation":"","options":["Abscess","Ulcer","Cyst","Haematoma"],"correctIndex":0,"explanation":"An abscess is a localized collection of pus due to suppurative inflammation.","explanationNe":"Abscess भनेको suppurative inflammation का कारण बनेको पिपको स्थानीय जमावट हो।","topic":"Inflammation"}'::jsonb,true),
('bmlt-generalpathology1-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"The cardinal signs of acute inflammation include all except:","translation":"","options":["Redness","Heat","Swelling","Pallor"],"correctIndex":3,"explanation":"Redness, heat, swelling, pain and loss of function are classic signs.","explanationNe":"रातोपन, तातोपन, सुन्निनु, दुखाइ र कार्यक्षमता घट्नु सूजनका मुख्य लक्षण हुन्।","topic":"Inflammation"}'::jsonb,true),
('bmlt-generalpathology1-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"The predominant leukocyte in most acute bacterial inflammation is:","translation":"","options":["Lymphocyte","Neutrophil","Eosinophil","Basophil"],"correctIndex":1,"explanation":"Neutrophils are the main early responders in acute bacterial inflammation.","explanationNe":"तीव्र ब्याक्टेरियल सूजनमा न्युट्रोफिल प्रमुख प्रारम्भिक कोष हो।","topic":"Inflammation"}'::jsonb,true),
('bmlt-generalpathology1-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"The predominant cells in many chronic inflammatory lesions are:","translation":"","options":["Neutrophils only","Macrophages and lymphocytes","Red blood cells","Platelets"],"correctIndex":1,"explanation":"Chronic inflammation commonly features macrophages, lymphocytes and plasma cells.","explanationNe":"दीर्घकालीन सूजनमा म्याक्रोफेज, लिम्फोसाइट र प्लाज्मा कोष देखिन्छन्।","topic":"Inflammation"}'::jsonb,true),
('bmlt-generalpathology1-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"A granuloma is characterized by aggregates of:","translation":"","options":["Epithelioid macrophages","Red blood cells","Platelets","Adipocytes"],"correctIndex":0,"explanation":"Granulomas are organized collections of activated macrophages, often with lymphocytes.","explanationNe":"Granuloma सक्रिय macrophage को व्यवस्थित समूह हो, प्रायः lymphocyte सहित।","topic":"Inflammation"}'::jsonb,true),
('bmlt-generalpathology1-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"The process that stops bleeding after vessel injury is:","translation":"","options":["Haemostasis","Haemolysis","Fibrinolysis","Haematopoiesis"],"correctIndex":0,"explanation":"Haemostasis involves vascular response, platelet plug formation and coagulation.","explanationNe":"Haemostasis मा रक्तनली प्रतिक्रिया, platelet plug र coagulation समावेश हुन्छ।","topic":"Haemodynamic disorders"}'::jsonb,true),
('bmlt-generalpathology1-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"A thrombus is:","translation":"","options":["A clot formed within the circulation during life","A clot formed only after death","A collection of air in tissue","A bacterial colony"],"correctIndex":0,"explanation":"Thrombosis is formation of a solid blood clot within the cardiovascular system during life.","explanationNe":"जीवित अवस्थामा रक्तसञ्चार प्रणालीभित्र बनेको रगतको थक्का thrombus हो।","topic":"Haemodynamic disorders"}'::jsonb,true),
('bmlt-generalpathology1-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"An embolus is most commonly:","translation":"","options":["A detached intravascular mass travelling in blood","A fixed tissue scar","A benign tumour","A platelet precursor"],"correctIndex":0,"explanation":"An embolus travels from its site of origin to another vascular location.","explanationNe":"Embolus आफ्नो उत्पत्ति स्थानबाट छुटेर रगतसँग अर्को ठाउँमा पुग्छ।","topic":"Haemodynamic disorders"}'::jsonb,true),
('bmlt-generalpathology1-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"Excess fluid accumulation in interstitial tissues is called:","translation":"","options":["Oedema","Ischaemia","Atrophy","Fibrosis"],"correctIndex":0,"explanation":"Oedema is abnormal accumulation of fluid in interstitial spaces or cavities.","explanationNe":"ऊतकको बीचको खाली स्थान वा cavity मा असामान्य तरल जम्मा हुनु oedema हो।","topic":"Haemodynamic disorders"}'::jsonb,true),
('bmlt-generalpathology1-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"A reduction in blood supply to a tissue is called:","translation":"","options":["Hyperaemia","Ischaemia","Congestion","Haemorrhage"],"correctIndex":1,"explanation":"Ischaemia is inadequate blood supply, reducing oxygen and nutrient delivery.","explanationNe":"Ischaemia भनेको ऊतकमा पर्याप्त रगत नपुग्नु हो।","topic":"Haemodynamic disorders"}'::jsonb,true),
('bmlt-generalpathology1-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"A benign tumour usually:","translation":"","options":["Invades surrounding tissue","Metastasizes early","Remains localized and does not metastasize","Always causes death"],"correctIndex":2,"explanation":"Benign tumours are generally localized and lack metastatic spread.","explanationNe":"Benign tumour सामान्यतया सीमित रहन्छ र metastasis गर्दैन।","topic":"Neoplasia"}'::jsonb,true),
('bmlt-generalpathology1-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"Spread of malignant tumour to a distant site is called:","translation":"","options":["Differentiation","Metastasis","Encapsulation","Hyperplasia"],"correctIndex":1,"explanation":"Metastasis is the spread of malignant cells to non-contiguous sites.","explanationNe":"Malignant कोष टाढाको स्थानमा फैलिनुलाई metastasis भनिन्छ।","topic":"Neoplasia"}'::jsonb,true),
('bmlt-generalpathology1-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"A malignant tumour arising from epithelial tissue is generally called:","translation":"","options":["Sarcoma","Carcinoma","Lymphoma","Leukaemia"],"correctIndex":1,"explanation":"Carcinomas arise from epithelial cells.","explanationNe":"Epithelial tissue बाट उत्पन्न हुने malignant tumour carcinoma हो।","topic":"Neoplasia"}'::jsonb,true),
('bmlt-generalpathology1-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"A malignant tumour of mesenchymal origin is generally called:","translation":"","options":["Carcinoma","Sarcoma","Adenoma","Papilloma"],"correctIndex":1,"explanation":"Sarcomas arise from mesenchymal or connective tissues.","explanationNe":"Mesenchymal वा connective tissue बाट उत्पन्न malignant tumour sarcoma हो।","topic":"Neoplasia"}'::jsonb,true),
('bmlt-generalpathology1-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"A deficiency of iron most commonly causes:","translation":"","options":["Megaloblastic anaemia","Microcytic hypochromic anaemia","Aplastic anaemia","Haemolytic anaemia"],"correctIndex":1,"explanation":"Iron deficiency typically produces microcytic hypochromic red cells.","explanationNe":"फलामको कमीले प्रायः साना र कम रङ भएका RBC सहितको anaemia गराउँछ।","topic":"Systemic pathology"}'::jsonb,true),
('bmlt-generalpathology1-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"Vitamin B12 deficiency may cause:","translation":"","options":["Megaloblastic anaemia","Iron overload","Polycythaemia","Thrombocytosis"],"correctIndex":0,"explanation":"Vitamin B12 deficiency impairs DNA synthesis and causes megaloblastic anaemia.","explanationNe":"Vitamin B12 को कमीले DNA synthesis बिगारी megaloblastic anaemia गराउँछ।","topic":"Systemic pathology"}'::jsonb,true),
('bmlt-generalpathology1-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"Jaundice results from increased levels of:","translation":"","options":["Bilirubin","Albumin","Urea","Creatinine"],"correctIndex":0,"explanation":"Jaundice is yellow discoloration due to increased bilirubin.","explanationNe":"Bilirubin बढ्दा छाला र आँखामा पहेँलोपन देखिन्छ, जसलाई jaundice भनिन्छ।","topic":"Systemic pathology"}'::jsonb,true),
('bmlt-generalpathology1-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"Which necrosis is classically associated with myocardial infarction?","translation":"","options":["Coagulative","Liquefactive","Caseous","Fat"],"correctIndex":0,"explanation":"Ischaemic injury in most solid organs produces coagulative necrosis; the brain is an exception.","explanationNe":"धेरैजसो ठोस अंगमा ischemia ले coagulative necrosis गराउँछ; मस्तिष्क अपवाद हो।","topic":"Cell injury"}'::jsonb,true),
('bmlt-generalpathology1-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"Liquefactive necrosis is classically seen in:","translation":"","options":["Brain infarction","Myocardial infarction","Renal infarction","Splenic infarction"],"correctIndex":0,"explanation":"Brain infarcts typically undergo liquefactive necrosis.","explanationNe":"मस्तिष्कको infarction मा प्रायः liquefactive necrosis हुन्छ।","topic":"Cell injury"}'::jsonb,true),
('bmlt-generalpathology1-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"Caseous necrosis is classically associated with:","translation":"","options":["Tuberculosis","Hypertension","Diabetes mellitus","Atherosclerosis"],"correctIndex":0,"explanation":"Tuberculosis commonly produces caseating granulomatous inflammation.","explanationNe":"क्षयरोगमा caseous प्रकारको granulomatous inflammation देखिन सक्छ।","topic":"Cell injury"}'::jsonb,true),
('bmlt-generalpathology1-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"Fat necrosis is commonly associated with acute inflammation of the:","translation":"","options":["Pancreas","Thyroid","Spleen","Bladder"],"correctIndex":0,"explanation":"Pancreatic lipases can cause enzymatic fat necrosis in acute pancreatitis.","explanationNe":"Acute pancreatitis मा pancreatic lipase ले fat necrosis गराउन सक्छ।","topic":"Cell injury"}'::jsonb,true),
('bmlt-generalpathology1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"Which mediator is strongly associated with increased vascular permeability in acute inflammation?","translation":"","options":["Histamine","Insulin","Thyroxine","Erythropoietin"],"correctIndex":0,"explanation":"Histamine released from mast cells increases vascular permeability.","explanationNe":"Mast cell बाट निस्कने histamine ले रक्तनलीको permeability बढाउँछ।","topic":"Inflammation"}'::jsonb,true),
('bmlt-generalpathology1-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"Fever during inflammation is mediated in part by:","translation":"","options":["Prostaglandin E2","Haemoglobin","Bile salts","Insulin"],"correctIndex":0,"explanation":"Prostaglandin E2 acts in the hypothalamus to raise the temperature set point.","explanationNe":"Prostaglandin E2 ले hypothalamus मा तापक्रमको set point बढाउन मद्दत गर्छ।","topic":"Inflammation"}'::jsonb,true),
('bmlt-generalpathology1-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"The main cells responsible for antibody production are:","translation":"","options":["Plasma cells","Neutrophils","Erythrocytes","Platelets"],"correctIndex":0,"explanation":"Plasma cells are differentiated B lymphocytes that secrete antibodies.","explanationNe":"Plasma cell परिपक्व B lymphocyte हो जसले antibody उत्पादन गर्छ।","topic":"Immunopathology"}'::jsonb,true),
('bmlt-generalpathology1-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"An exaggerated immune response to an otherwise harmless antigen is:","translation":"","options":["Hypersensitivity","Tolerance","Haemostasis","Metaplasia"],"correctIndex":0,"explanation":"Hypersensitivity is an excessive or inappropriate immune response causing tissue injury.","explanationNe":"हानिकारक नभएको antigen प्रति अत्यधिक प्रतिरक्षा प्रतिक्रिया hypersensitivity हो।","topic":"Immunopathology"}'::jsonb,true),
('bmlt-generalpathology1-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"Type I hypersensitivity is primarily mediated by:","translation":"","options":["IgE","IgG only","IgM only","T-cell cytotoxicity"],"correctIndex":0,"explanation":"Type I reactions involve IgE and mast-cell mediator release.","explanationNe":"Type I hypersensitivity मा IgE र mast cell बाट mediator निस्कन्छ।","topic":"Immunopathology"}'::jsonb,true),
('bmlt-generalpathology1-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"An autoimmune disease occurs when the immune system:","translation":"","options":["Attacks self-antigens","Cannot recognize microbes","Stops producing all antibodies","Only attacks parasites"],"correctIndex":0,"explanation":"Autoimmunity involves loss of tolerance to self-antigens.","explanationNe":"Autoimmunity मा शरीरले आफ्नै antigen प्रति tolerance गुमाउँछ।","topic":"Immunopathology"}'::jsonb,true),
('bmlt-generalpathology1-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"A deficiency of platelets is termed:","translation":"","options":["Thrombocytopenia","Leukocytosis","Polycythaemia","Neutrophilia"],"correctIndex":0,"explanation":"Thrombocytopenia means a reduced platelet count.","explanationNe":"Platelet संख्या घट्नुलाई thrombocytopenia भनिन्छ।","topic":"Systemic pathology"}'::jsonb,true),
('bmlt-generalpathology1-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"An increased total white blood cell count is called:","translation":"","options":["Leukopenia","Leukocytosis","Thrombocytopenia","Anaemia"],"correctIndex":1,"explanation":"Leukocytosis refers to an elevated white blood cell count.","explanationNe":"WBC को संख्या बढ्नुलाई leukocytosis भनिन्छ।","topic":"Systemic pathology"}'::jsonb,true),
('bmlt-generalpathology1-mock-013','BMLT','BMLT NHPC Licensing','mock','free',13,'{"question":"A reduced haemoglobin concentration is a defining feature of:","translation":"","options":["Anaemia","Polycythaemia","Leukaemia","Thrombosis"],"correctIndex":0,"explanation":"Anaemia is defined by reduced haemoglobin concentration for age and sex.","explanationNe":"उमेर र लिङ्गअनुसार haemoglobin कम हुनु anaemia को मुख्य विशेषता हो।","topic":"Systemic pathology"}'::jsonb,true),
('bmlt-generalpathology1-mock-014','BMLT','BMLT NHPC Licensing','mock','free',14,'{"question":"The most common type of shock due to severe blood loss is:","translation":"","options":["Hypovolaemic shock","Cardiogenic shock","Septic shock","Neurogenic shock"],"correctIndex":0,"explanation":"Major blood loss reduces circulating volume and causes hypovolaemic shock.","explanationNe":"धेरै रगत गुम्दा circulating volume घटेर hypovolaemic shock हुन्छ।","topic":"Haemodynamic disorders"}'::jsonb,true),
('bmlt-generalpathology1-mock-015','BMLT','BMLT NHPC Licensing','mock','free',15,'{"question":"Septic shock is associated with:","translation":"","options":["Severe infection and dysregulated host response","Simple dehydration only","Isolated bone fracture","Vitamin deficiency"],"correctIndex":0,"explanation":"Septic shock is a life-threatening circulatory and cellular response to infection.","explanationNe":"गम्भीर संक्रमणप्रति शरीरको अनियन्त्रित प्रतिक्रियाले septic shock गराउँछ।","topic":"Haemodynamic disorders"}'::jsonb,true),
('bmlt-generalpathology1-mock-016','BMLT','BMLT NHPC Licensing','mock','free',16,'{"question":"Atherosclerosis primarily affects:","translation":"","options":["Large and medium-sized arteries","Veins only","Lymphatic vessels","Capillaries only"],"correctIndex":0,"explanation":"Atherosclerosis involves lipid-rich plaques in the intima of arteries.","explanationNe":"Atherosclerosis मा धमनीको भित्री तहमा बोसोयुक्त plaque जम्छ।","topic":"Haemodynamic disorders"}'::jsonb,true),
('bmlt-generalpathology1-mock-017','BMLT','BMLT NHPC Licensing','mock','free',17,'{"question":"The term dysplasia refers to:","translation":"","options":["Disordered cellular growth and maturation","Increase in cell size only","Normal tissue repair","Programmed cell death"],"correctIndex":0,"explanation":"Dysplasia describes abnormal epithelial growth, maturation and organization.","explanationNe":"Dysplasia मा epithelial कोषको वृद्धि, परिपक्वता र व्यवस्था असामान्य हुन्छ।","topic":"Neoplasia"}'::jsonb,true),
('bmlt-generalpathology1-mock-018','BMLT','BMLT NHPC Licensing','mock','free',18,'{"question":"A tumour that arises from glandular epithelium and is benign is called:","translation":"","options":["Adenoma","Adenocarcinoma","Fibrosarcoma","Lymphoma"],"correctIndex":0,"explanation":"An adenoma is a benign neoplasm of glandular epithelium.","explanationNe":"Glandular epithelium बाट बनेको benign tumour adenoma हो।","topic":"Neoplasia"}'::jsonb,true),
('bmlt-generalpathology1-mock-019','BMLT','BMLT NHPC Licensing','mock','free',19,'{"question":"A malignant tumour of gland-forming epithelium is:","translation":"","options":["Adenocarcinoma","Adenoma","Lipoma","Leiomyoma"],"correctIndex":0,"explanation":"Adenocarcinoma is a malignant epithelial tumour with glandular differentiation.","explanationNe":"Glandular differentiation भएको malignant epithelial tumour adenocarcinoma हो।","topic":"Neoplasia"}'::jsonb,true),
('bmlt-generalpathology1-mock-020','BMLT','BMLT NHPC Licensing','mock','free',20,'{"question":"The spread of cancer through lymphatic channels is particularly common in:","translation":"","options":["Carcinomas","Benign lipomas","Simple cysts","Hamartomas"],"correctIndex":0,"explanation":"Carcinomas commonly spread through lymphatics, though patterns vary by tumour.","explanationNe":"Carcinoma मा lymphatic मार्गबाट फैलिने प्रवृत्ति सामान्य हुन्छ, तर tumour अनुसार फरक पर्छ।","topic":"Neoplasia"}'::jsonb,true),
('bmlt-generalpathology1-mock-021','BMLT','BMLT NHPC Licensing','mock','free',21,'{"question":"The term infarction means:","translation":"","options":["Area of ischaemic necrosis","Increase in blood flow","Excess tissue growth","Fluid accumulation"],"correctIndex":0,"explanation":"An infarct is an area of tissue necrosis due to inadequate blood supply.","explanationNe":"रगतको आपूर्ति नपुगेर बनेको ऊतक necrosis को क्षेत्र infarct हो।","topic":"Haemodynamic disorders"}'::jsonb,true),
('bmlt-generalpathology1-mock-022','BMLT','BMLT NHPC Licensing','mock','free',22,'{"question":"A purulent exudate is rich in:","translation":"","options":["Neutrophils and cellular debris","Red cells only","Albumin only","Bile pigments"],"correctIndex":0,"explanation":"Pus contains neutrophils, dead cells and often microorganisms.","explanationNe":"पिपमा न्युट्रोफिल, मृत कोष र प्रायः सूक्ष्मजीव हुन्छन्।","topic":"Inflammation"}'::jsonb,true),
('bmlt-generalpathology1-mock-023','BMLT','BMLT NHPC Licensing','mock','free',23,'{"question":"Granulation tissue in wound healing contains abundant:","translation":"","options":["New capillaries and fibroblasts","Mature cartilage only","Adipocytes only","Neurons"],"correctIndex":0,"explanation":"Granulation tissue consists of proliferating capillaries, fibroblasts and inflammatory cells.","explanationNe":"Granulation tissue मा नयाँ capillary, fibroblast र inflammatory cell प्रशस्त हुन्छन्।","topic":"Tissue repair"}'::jsonb,true),
('bmlt-generalpathology1-mock-024','BMLT','BMLT NHPC Licensing','mock','free',24,'{"question":"Collagen deposition during wound healing is mainly performed by:","translation":"","options":["Fibroblasts","Neutrophils","Erythrocytes","Platelets"],"correctIndex":0,"explanation":"Fibroblasts synthesize collagen and extracellular matrix during repair.","explanationNe":"घाउ निको हुँदा fibroblast ले collagen र extracellular matrix बनाउँछ।","topic":"Tissue repair"}'::jsonb,true),
('bmlt-generalpathology1-mock-025','BMLT','BMLT NHPC Licensing','mock','free',25,'{"question":"A keloid is caused by:","translation":"","options":["Excessive collagen deposition during healing","Failure of platelet formation","Loss of melanin","Acute bacterial infection only"],"correctIndex":0,"explanation":"Keloids are raised scars caused by excessive collagen deposition beyond wound boundaries.","explanationNe":"अत्यधिक collagen जम्मा भएर घाउको सीमाभन्दा बाहिर बढेको उठेको दाग keloid हो।","topic":"Tissue repair"}'::jsonb,true),
('bmlt-generalpathology1-mock-026','BMLT','BMLT NHPC Licensing','mock','free',26,'{"question":"The term fibrosis refers to:","translation":"","options":["Excess deposition of connective tissue","Loss of all blood cells","Formation of pus","Breakdown of haemoglobin"],"correctIndex":0,"explanation":"Fibrosis is excessive accumulation of collagen-rich connective tissue.","explanationNe":"Collagenयुक्त connective tissue अत्यधिक जम्मा हुनुलाई fibrosis भनिन्छ।","topic":"Tissue repair"}'::jsonb,true)
