-- BMLT NHPC preparation: General Pathology & Pathophysiology Batch 1
-- 25 MCQ Practice + 25 Mock Test questions
begin;
on conflict (content_id) do nothing;
commit;

select content_type, count(*) as question_count
from public.learning_content
where faculty='BMLT'
  and subject='BMLT NHPC Licensing'
  and content_data->>'topic' in ('General pathology','Cell injury','Cell adaptation','Inflammation','Haemodynamic disorders','Neoplasia','Systemic pathology','Immunopathology','Tissue repair')
group by content_type
order by content_type;
